  if(active==='School Requests'){
   const {data,error}=await client.from('school_requests').select('id,school_name,school_code,school_type,contact_person,contact_email,phone,alternate_phone,city,state,district,pincode,address,board,affiliation_number,classes_offered,instruction_medium,academic_session,estimated_students,estimated_teachers,branches_count,website,logo_url,document_urls,message,status,created_at').order('created_at',{ascending:false}).limit(200);if(error)throw error;
   panel.innerHTML=`<div class="panel-head"><h2>School registration requests</h2><span class="muted">${data.length} requests</span></div>${data.length?`<div class="table-wrap"><table><thead><tr><th>School / Code</th><th>Contact</th><th>Location</th><th>Board / Classes</th><th>Submitted</th><th>Status</th><th>Review</th></tr></thead><tbody>${data.map(x=>`<tr><td>${esc(x.school_name)}<br><small>${esc(x.school_code||'')} · ${esc(x.school_type||'')}</small></td><td>${esc(x.contact_person)}<br>${esc(x.contact_email)}<br>${esc(x.phone)}</td><td>${esc([x.city,x.district,x.state,x.pincode].filter(Boolean).join(', ')||'—')}<br>${esc(x.address||'')}</td><td>${esc(x.board||'—')}<br><small>${esc((x.classes_offered||[]).join(', '))}</small></td><td>${esc(x.created_at)}</td><td>${esc(x.status)}</td><td>${x.status==='pending'?`<button class="primary small" data-review-request="${esc(x.id)}" data-decision="approved">Approve</button> <button class="danger small" data-review-request="${esc(x.id)}" data-decision="rejected">Reject</button>`:'Reviewed'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No registration requests yet.</div>'}`;
   panel.querySelectorAll('[data-review-request]').forEach(btn=>btn.onclick=async()=>{const decision=btn.dataset.decision;const reason=decision==='rejected'?prompt('Rejection reason (optional):')||'':'';if(!confirm(`${decision==='approved'?'Approve':'Reject'} this school request?`))return;btn.disabled=true;try{const {data,error}=await client.functions.invoke('admin-account-action',{body:{action:'review_school_request',request_id:btn.dataset.reviewRequest,decision,reason}});if(error||data?.error)throw new Error(data?.error||error.message);appMessage(decision==='approved'?'School approved and school record created.':'School request rejected.','success');renderPanel()}catch(err){appMessage(err.message,'error')}finally{btn.disabled=false}});return;
  }
