    const mapRows=mappings.map(m=>{const st=students.find(x=>x.id===m.student_id),dv=devices.find(x=>x.id===m.device_id);return '<tr><td>'+esc(dv?.device_name||'—')+'</td><td>'+esc(m.machine_user_id)+'</td><td>'+esc(st?.student_name||'Student unavailable')+'</td><td>'+esc(st?.class_name||'—')+'</td><td>'+esc(st?.section||'—')+'</td></tr>'}).join('');
