  async function fillSections(schoolId,cls){sectionSel.innerHTML='<option value="">All sections</option>';if(!cls||!schoolId)return;let q=client.from('students').select('section').eq('school_id',schoolId).eq('class_name',cls).order('section');const r=await q;if(r.error)throw r.error;const sections=[...new Set((r.data||[]).map(x=>(x.section||'').trim()).filter(Boolean))];sectionSel.innerHTML='<option value="">All sections</option>'+sections.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');}
  classSel.onchange=()=>fillSections(isSuper?schoolSel.value:profile.school_id,classSel.value).catch(e=>appMessage(e.message,'error')); 
